  "cost.accuracyMethod": "Verificato il {when} su {n} destinazioni in {countries} paesi. Per ciascuna abbiamo confrontato il costo del cibo per persona al giorno con quanto implica l'indice dei livelli di prezzo di Eurostat per il suo paese, escludendo quel paese dal confronto. Il {pct}% è rimasto entro {eur} EUR; contando i paesi invece delle località, l'intervallo va dal {lo}% al {hi}%. Questo verifica come i prezzi del cibo differiscono tra paesi, non il livello esatto in una località. Per i letti non pubblichiamo ancora una cifra di accuratezza: le località che abbiamo potuto confrontare con annunci reali sono troppo poche.",
