  "pass.freeSentence": "Pianificare è gratis. Un Trip Pass aggiunge esportazioni, più viaggi salvati e più piani con l'IA.",
  "pass.seeAll": "Vedi tutti i prezzi",
  "pricing.back": "Indietro",
  "pricing.docTitle": "Prezzi del Trip Pass",
  "pricing.compareTitle": "Cosa resta gratis e cosa aggiunge un pass",
  "pricing.passCol": "Un Trip Pass aggiunge",
  "pricing.free1": "Ogni luogo, con prezzo e mappa",
  "pricing.free2": "Il pianificatore di viaggi e quello dei giorni",
