  "pricing.plansTitle": "Due modi di pagare",
  "pricing.qTitle": "Prima di pagare",
  "pricing.afterQ": "Cosa succede dopo {days} giorni?",
  "pricing.afterA": "Il Trip Pass si ferma. Niente si rinnova e non viene addebitato altro. I tuoi viaggi restano salvati e pianificare resta gratis. Le esportazioni e i piani in più aspettano un nuovo pass.",
  "pricing.restoreQ": "Ho pagato su un altro dispositivo. Dov'è il mio pass?",
  "pricing.restoreA": "Il pass appartiene al tuo account, non al dispositivo. Accedi con l'account con cui hai pagato e lo trovi. Ancora niente? Scrivi a {email}.",
  "pricing.restoreGo": "Controlla di nuovo il mio pass",
  "pricing.restoreSignIn": "Accedi",
  "pricing.restoreDone": "Controllato. Il tuo piano: {name}.",
  "pass.continueAddDays": "Aggiungi {n} giorni, {price}",
  "pass.carryOver": "I giorni rimasti del tuo Trip Pass restano.",
  "pass.current1": "Ti resta 1 giorno di {name}.",
  "pass.cancellingNote": "Il tuo piano annuale termina il {date}. Tienilo e si rinnova come prima.",
  "pass.resume": "Mantieni il mio piano annuale",
  "account.fqgPlanning": "Pianificare",
  "account.fqgPrices": "Prezzi",
  "account.fqgPasses": "Pass e pagamento",
  "account.fqgAccount": "Account e dati",
  "account.fq.planQ": "Come pianifico un viaggio?",
  "account.fq.planA": "Apri il pianificatore di viaggio, scegli date e luoghi, e Carta ordina le tappe e dà un prezzo a ogni letto, giorno e tratta. Il pianificatore giornaliero riempie poi ogni giorno ora per ora.",
  "account.fq.togetherQ": "Posso pianificare un viaggio con gli amici?",
  "account.fq.togetherA": "Sì. In I miei viaggi scegli Invita su un viaggio: chi ha il link può accedere e modificare il percorso con te. Un link di sola lettura funziona senza account.",
  "account.fq.bookQ": "Posso prenotare tramite Carta?",
  "account.fq.bookA": "No. Carta prezza e pianifica il viaggio, poi ti manda alla compagnia aerea, al treno o all'host per prenotare direttamente da loro.",
  "account.fq.missingQ": "Il mio paese manca. E ora?",
  "account.fq.missingA": "Il pianificatore giornaliero funziona lo stesso: scrivi il paese e lo cerca dal vivo. Il catalogo cresce a ogni aggiornamento.",
  "account.fq.differentQ": "In cosa Carta è diversa da Google Maps o Wanderlog?",
  "account.fq.differentA": "Google Maps ti ci porta e Wanderlog conserva il piano che hai scritto tu, ma nessuna delle due sa quanto costa un letto o un giorno. Carta pianifica tutto il viaggio in un unico posto, con quanto costa ogni giorno: un letto più cibo e bevande, con un prezzo per ogni luogo. Carta non naviga mai, quindi ogni giorno e ogni tratta si apre in Google Maps.",
  "account.fq.dayQ": "Cosa include il prezzo al giorno?",
  "account.fq.dayA": "Una persona, un giorno: un letto per la notte più cibo e bevande (un pasto al tavolo, un pasto veloce, bevande), secondo il tuo Lifestyle. Non inclusi: il viaggio per arrivarci, i trasporti locali e i biglietti.",
  "account.fq.estQ": "Perché un prezzo è segnato stim.?",
  "account.fq.estA": "È una stima: i prezzi del paese non sono stati misurati, quindi Carta usa il livello della nazione. Un prezzo misurato non ha segni.",
  "account.fq.lifestyleQ": "Perché i prezzi sono cambiati quando ho cambiato Lifestyle?",
  "account.fq.lifestyleA": "Perché sono i tuoi prezzi. Un letto in dormitorio e un alloggio intero con cena fuori sono viaggi diversi, e un'unica impostazione guida ogni cifra dell'app.",
  "account.fq.flightsQ": "Carta mostra i prezzi dei voli?",
  "account.fq.flightsA": "Sì. Carta mostra il volo più economico di Google Flights per i tuoi giorni, con la compagnia, gli orari e quando è stato verificato, più il costo abituale del bagaglio come stima. Un biglietto che aggiungi lo sostituisce.",
  "account.fq.addsQ": "Cosa aggiunge un pass?",
  "account.fq.addsA": "La versione gratuita tiene {freePlans} piani del bot Carta e un viaggio salvato. Un Trip Pass aggiunge esportazioni in PDF, calendario e mappa, tutti i viaggi salvati, la lettura delle prenotazioni, più piani giornalieri del bot Carta e ricerche dal vivo di eventi e orari. Condividere un viaggio e pianificare con gli amici restano gratuiti.",
  "account.fq.differenceQ": "Che differenza c'è tra il Trip Pass e il piano annuale?",
  "account.fq.differenceA": "Il Trip Pass costa {tripPrice} una volta e dura {tripDays} giorni, senza rinnovo. Il piano annuale costa {yearPrice} all'anno e si rinnova finché non disdici.",
  "account.fq.cancelQ": "Come disdico il piano annuale?",
  "account.fq.cancelA": "In Account, sotto Il tuo piano, scegli Disdici il piano annuale. Dura fino alla fine dell'anno pagato e non viene addebitato altro.",
  "account.fq.refundQ": "Posso avere un rimborso?",
  "account.fq.refundA": "Sì, entro 14 giorni dal pagamento se non hai usato il pass o il piano. Scrivi a {email} dall'indirizzo del tuo account.",
  "account.fq.needQ": "Mi serve un account?",
  "account.fq.needA": "Non per esplorare o pianificare. Un account tiene i tuoi viaggi su ogni dispositivo, apre il bot Carta e ti fa pianificare con gli amici.",
  "account.fq.whereQ": "Dove sono salvati i miei viaggi?",
  "account.fq.whereA": "Sul tuo account quando hai effettuato l'accesso, quindi si aprono su ogni dispositivo. Senza accesso restano in questo browser.",
  "account.fq.deleteQ": "Come elimino account e dati?",
  "account.fq.deleteA": "In Account apri I tuoi dati e scegli Elimina il mio account. Tutto sparisce subito dai server di Carta; prima puoi scaricarne una copia.",
