  "ac.ai": "IA e lettore di prenotazioni",
  "ac.aiPlanH": "Piani del giorno del bot Carta",
  "ac.aiPlanP": "Quando il bot Carta pianifica una giornata, Carta invia a Gemini di Google il luogo, la data, quanti siete, le tue risposte e ciò che hai scritto, e un elenco di tappe dal proprio catalogo. Passa dal server di Carta, che custodisce la chiave.",
  "ac.aiWhereH": "Dove andare",
  "ac.aiWhereP": "Quando chiedi al bot dove andare, invia allo stesso modo le tue risposte e le città vicine del catalogo.",
  "ac.aiBookH": "Lettore di prenotazioni",
  "ac.aiBookP": "Quando aggiungi una conferma di prenotazione, il file o il testo e le tappe e le date del viaggio vengono inviati a Gemini per la lettura. Nomi e recapiti restano fuori dalla risposta, e il risultato viene conservato 24 ore così un nuovo tentativo non costa nulla.",
  "ac.aiNotH": "Mai inviato",
  "ac.aiNotP": "Il tuo nome, la tua email e la tua password non vengono inviati a Gemini.",
  "ac.deleteEndsYear": "Il tuo piano annuale viene prima disdetto, così non viene addebitato altro.",
  "ac.deleteEndsTrip": "Il tuo Trip Pass termina con l'account. Non si rinnova.",
  "ac2.emails": "Email",
  "ac2.tripReminders": "Promemoria di viaggio",
  "ac2.priceDrops": "Cali di prezzo nei luoghi salvati",
  "ac2.emailsError": "Non è stato salvato. Riprova.",
  "ac2.cookies": "Cookie e archiviazione",
  "ac2.contents": "Indice",
  "ac2.ckIntro": "Carta non imposta cookie e non usa analisi, pubblicità o tracciamento. Per questo non c’è un banner dei cookie. Ecco cosa conserva l’app, e perché.",
  "ac2.ckDeviceH": "In questo browser",
  "ac2.ckDeviceP": "Impostazioni, lingua, luoghi e liste salvati, viaggi, piani del giorno, note e chat con Carta restano nella memoria di questo browser, così li ritrovi quando torni. Senza account restano su questo dispositivo.",
  "ac2.ckFilesH": "File e uso offline",
  "ac2.ckFilesP": "Biglietti e file aggiunti a un giorno restano nel database di questo browser. L’app conserva una copia dei propri file per aprirsi in fretta e funzionare offline. Se attivi Chiedi a Carta su questo dispositivo, anche il suo modello linguistico resta qui.",
  "ac2.ckSignInH": "Accesso",
  "ac2.ckSignInP": "Quando accedi, Supabase conserva la sessione nella memoria di questo browser, così resti connesso. Uscire la cancella.",
  "ac2.ckPayH": "Pagamento",
  "ac2.ckPayP": "Il pagamento avviene sulla pagina di pagamento di Stripe. Lì Stripe imposta i cookie che servono per un pagamento sicuro e contro le frodi. Carta non vede mai la tua carta.",
  "ac2.ckOtherH": "Foto e mappe",
  "ac2.ckOtherP": "Foto e tasselli della mappa arrivano da Wikimedia Commons, CARTO, OpenStreetMap e dai server di Carta. Carta non aggiunge tracciamento a queste richieste.",
  "ac2.ckClearH": "Cancellare",
  "ac2.ckClearP": "Cancella i dati di questo sito nelle impostazioni del browser per rimuovere tutto ciò che è qui. Ciò che è nel tuo account resta lì finché non lo cancelli in Account, I tuoi dati.",
